import{PathCombat,enemyHint}from'./path-combat.js';
export class TrailNavigator{
 constructor(state,onArrive=()=>{}){this.state=state;this.onArrive=onArrive;this.player={...START};this.heading=Math.PI;this.path=[];this.moving=false;this.level=0;this.area=state.area;this.y=0;this.vy=0;this.grounded=true;this.jumpStage='ground';this.jumpTimer=0;this.cooldown=0;this.radius=.24;this.height=.65;this.solids=[];this.destination=null;this.blocked=false;this.course=null;this.courseTime=0;this.mode='relaxed';this.recovery=0;this.invincible=0;this.events={};this.jumpBuffer=0;this.crumble=new Map();}
 // onFoot keeps a navigator walking (no runs), for tools and on-foot mechanics checks.
 enableTraversal(mode='relaxed',events=this.events){if(RUNNER&&!this.onFoot)this.runner??=new RunnerControl();if(this.rushEnabled&&this.rushExpedition!==this.state.id){this.rush=new RushMotion();this.rush.best=this.state.rushStats?.bestChain||0;this.rushExpedition=this.state.id;}this.mode=mode;this.events=events;this.course=sectionsFor(this.state,mode);travelState(this.state);if(this.combat?.state!==this.state){this.combat=new PathCombat(this);this.combat.state=this.state;this.crumble.clear();}else this.combat.sync();this.trials??=new PathTrials(this);}
 get section(){return this.course?.find(s=>s.index===this.state.index)||null;}
 setState(state){this.state=state;if(this.course)this.enableTraversal(this.mode);this.stop();this.restore(state.position);this.heading=state.heading||Math.PI;}
 setLevel(level){if(this.level!==level){this.pickupBounds=null;this.bodyProfile=null;}this.level=level;this.height=FORM_HEIGHTS[level];this.radius=this.bodyProfile?Math.min(this.bodyProfile.halfWidth,this.bodyProfile.halfDepth):CREATURE_RADII[level];this.restore(this.player);}
 turnTo(yaw){const before=this.heading;this.heading=yaw;if(this.bodyProfile&&!this.clear(this.player.x,this.player.z)){this.heading=before;return false;}return true;}
 applyBodyProfile(body){this.bodyProfile=body;this.radius=Math.min(body.halfWidth,body.halfDepth);if(this.clear(this.player.x,this.player.z))return;const origin={...this.player},height=this.support(origin);for(let d=.15;d<=4;d+=.15)for(const a of[Math.PI,-Math.PI/2,Math.PI/2,Math.PI*.75,-Math.PI*.75,0]){const q={x:origin.x+Math.sin(this.heading+a)*d,z:origin.z+Math.cos(this.heading+a)*d},y=this.support(q);if(y!==null&&Math.abs(y-(height??0))<.25&&this.clear(q.x,q.z,y)){this.player=q;this.cancelJump();return;}}const safe=this.state.travel?.safe;if(safe&&this.support(safe)!==null&&this.clear(safe.x,safe.z,this.support(safe))){this.player={x:safe.x,z:safe.z};this.cancelJump();}}

 setArea(area){this.area=area;this.stop();this.cancelJump();}
 support(p=this.player){if(this.runner?.running&&p===this.player)return this.runner.surface();return this.course?surfaceOnCourse(this.course,p,this.radius,this.crumble,this.courseTime):0;}
 restore(p){if(p&&trailAllowed(this.state,p,this.radius))this.player={x:p.x,z:p.z};else{const node=activeNode(this.state);this.player=node?approachPoint(node):{x:0,z:-Math.floor(this.state.index/4)*CHAPTER_LENGTH+2};}if(this.support()===null){const safe=this.state.travel?.safe,section=this.section;this.player=safe&&this.support(safe)!==null&&trailAllowed(this.state,safe,this.radius)?{x:safe.x,z:safe.z}:section?localPoint(section,1.5):{...START};}this.stop();this.cancelJump();}
 stop(){this.path=[];this.moving=false;this.destination=null;}
 cancelJump(){this.y=this.support()??0;this.vy=0;this.grounded=true;this.jumpStage='ground';this.jumpTimer=0;this.jumpBuffer=0;this.jumpAssisted=false;}
 requestBoost(){if(this.runner?.running)return this.runner.boost(this);if(!this.rushEnabled||this.recovery>0||this.section?.kind!=='coins'||this.section?.trial||this.combat?.blocking||this.trials?.blocking)return false;this.rush??=new RushMotion();return this.rush.start();}
 get jumping(){return this.jumpStage!=='ground';}
 get jumpAnimation(){return this.jumpStage==='ground'?null:this.jumpStage==='anticipation'?.15*this.jumpTimer/.1:this.jumpStage==='landing'?.78+.22*this.jumpTimer/.14:.15+.63*Math.min(1,(this.airTime||0)/(this.flightDuration||.6));}
 requestJump({assisted=false}={}){if(this.recovery>0)return false;if(!this.grounded&&this.jumpStage==='air'&&(this.airTime||0)<=.085&&this.vy<=0){this.jumpStage='air';this.vy=jumpTuning(this.level).velocity;this.airTime=0;this.flightDuration=jumpTuning(this.level).flight;this.jumpBuffer=0;return true;}if(this.jumping||!this.grounded||this.cooldown>0){if(this.jumpStage==='landing'||this.jumpStage==='air'&&this.vy<0||this.grounded&&this.cooldown>0)this.jumpBuffer=.16;return false;}this.jumpBuffer=0;this.jumpAssisted=assisted;this.jumpStage='anticipation';this.jumpTimer=0;return true;}
 requestRanged(){return this.combat?.requestAttack({ranged:true})||false;}
 requestAttack(){this.trials?.aim();return this.combat?.requestAttack()||false;}
 clear(x,z,y=this.y){if(this.trials&&!this.trials.clear({x,z}))return false;if(this.combat&&!this.combat.clear({x,z}))return false;const body=profileOf(this),c=capsule(body,{x,z},this.heading);if(![c.a,c.b].every(p=>trailAllowed(this.state,p,c.r)))return false;for(const s of this.solids){if(y>=(s.top||4))continue;if(circlesTouchBody(body,{x,z},this.heading,s))return false;}const top=this.support({x,z});if(top!==null&&top>y+(this.grounded?.245:.045))return false;return true;}
 go(x,z,id=null){if(!this.state.choices[Math.min(4,Math.floor(this.state.index/4))])return false;const node=activeNode(this.state);let target=node&&z<node.z+3.7?approachPoint(node):{x,z};const section=this.section;if(section?.trial&&!travelState(this.state).completed.includes(section.index)){const entrance=section.trial.kind==='crystals'?section.trial.s-3:2;if(courseCoordinates(section,target).s>entrance){if(courseCoordinates(section,this.player).s>=entrance-.3){this.stop();this.events.notice?.(trialHint(section));return false;}target=localPoint(section,entrance);id=null;}}if(section?.enemy&&this.combat?.blocking){const entrance=2.4;if(courseCoordinates(section,target).s>entrance){if(courseCoordinates(section,this.player).s>=entrance-.3){this.stop();this.events.notice?.(enemyHint(this.combat.blocking));return false;}target=localPoint(section,entrance);id=null;}}if(section&&['rocks','plants'].includes(section.kind)&&!travelState(this.state).completed.includes(section.index)){const entrance=section.kind==='rocks'?section.pool.from-1.4:section.plants[0].s-2.4,q=courseCoordinates(section,target);if(q.s>entrance&&courseCoordinates(section,this.player).s< section.length-1.4){if(courseCoordinates(section,this.player).s>=entrance-.3){this.stop();this.events.notice?.('Use movement and jump to cross this stretch.');return false;}target=localPoint(section,entrance);id=null;}}
  if(!this.clear(target.x,target.z,this.support(target)??0))return false;this.path=routeTo(this.state,this.player,target);this.destination=id;return true;
 }
 approach(){const node=activeNode(this.state);if(!node)return false;const target=approachPoint(node);if(Math.hypot(this.player.x-target.x,this.player.z-target.z)<1&&!this.jumping){this.onArrive(node.id);return true;}return this.go(target.x,target.z,node.id);}
 nearest(){if(this.trials?.blocking)return null;if(this.combat?.blocking)return null;const n=activeNode(this.state);return n&&Math.hypot(this.player.x-n.x,this.player.z-n.z)<5?{...n,distance:Math.hypot(this.player.x-n.x,this.player.z-n.z),name:n.object,action:n.type==='exit'?'Finish expedition':'Interact'}:null;}
 retrySafe(p){if(!p||!trailAllowed(this.state,p,this.radius))return false;const y=this.support(p);if(y===null||!this.clear(p.x,p.z,y))return false;for(const s of this.course||[]){const q=courseCoordinates(s,p);if(q.s<0||q.s>s.length||Math.abs(q.lateral)>3.4)continue;if(s.plants.some(v=>circlesTouchBody(profileOf(this,.3),p,this.heading,v,v.cloudRadius+.15)))return false;if(s.platforms.some(v=>(v.fragile||v.motion)&&Math.hypot(p.x-v.x,p.z-v.z)<v.r+.2))return false;const t=s.trial;if(t?.kind==='boulders'&&t.lanes.some(v=>Math.abs(q.s-v.s)<v.r+bodyExtent(profileOf(this,.6),this.heading,s.forward)+.25))return false;if(t?.kind==='thorns'&&t.rows.some(v=>Math.abs(q.s-v.s)<.35+bodyExtent(profileOf(this,.4),this.heading,s.forward)+.25))return false;if(t?.kind==='wind'&&q.s>3&&q.s<s.length-2&&!t.covers.some(c=>q.s<c.s-.3&&q.s>c.s-2.7&&Math.abs(q.lateral-c.lateral)<.9))return false;}return true;}
 retry(reason){const travel=travelState(this.state),section=this.section,origin={...this.player};this.crumble.clear();this.combat?.retry();const entrance=section?localPoint(section,1.5):START,safe=travel.safe,near=safe&&Math.hypot(safe.x-entrance.x,safe.z-entrance.z)<(section?.length||15)+8,candidates=[near?safe:null,entrance,...(section?[.5,1,2,2.5,3].flatMap(s=>[0,-1.2,1.2].map(l=>localPoint(section,s,l))):[]),this.state.checkpoint?.position,{x:0,z:-Math.min(4,Math.floor(this.state.index/4))*CHAPTER_LENGTH+2},START];const p=candidates.find(v=>this.retrySafe(v))||entrance;this.player={x:p.x,z:p.z};this.heading=p.heading??this.heading;this.stop();this.cancelJump();this.recovery=.4;this.invincible=1.8;travel.safe={...this.player,y:this.y,heading:this.heading};travel.retries++;this.rush?.reset();if(this.runner?.afterRetry(this)){travel.safe={...this.player,y:this.y,heading:this.heading};}this.retryInfo={reason,origin,restored:{...this.player},time:this.courseTime};this.events.retry?.(reason);}
 updateCrumble(dt){for(const section of this.course||[])for(const rock of section.platforms){if(!rock.fragile)continue;let c=this.crumble.get(rock.id);if(!c&&this.grounded&&Math.abs(this.y-rock.y)<.04&&Math.hypot(this.player.x-rock.x,this.player.z-rock.z)<rock.r){c={age:0,fallen:false};this.crumble.set(rock.id,c);}if(c){c.age+=dt;c.fallen=c.age>rock.crumbleAfter;if(c.age>rock.crumbleAfter+4)this.crumble.delete(rock.id);}}}
 updateTravel(){if(!this.course||this.recovery>0)return;const t=travelState(this.state),p=this.player;let safe=this.trials?.safe()??true;for(const section of this.course){const q=courseCoordinates(section,p);if(q.s< -2||q.s>section.length+2||Math.abs(q.lateral)>4)continue;for(const plant of section.plants){const distance=Math.hypot(p.x-plant.x,p.z-plant.z);if(circlesTouchBody(profileOf(this,.4),p,this.heading,plant,plant.cloudRadius+.25))safe=false;if(this.invincible<=0&&this.y<1.7&&circlesTouchBody(profileOf(this,.3),p,this.heading,plant,plant.cloudRadius)&&plantPhase(plant,this.courseTime)==='active'){this.retry('poison');return;}}
   for(const rawCoin of section.coins){const coin=coinPose(section,rawCoin,this.courseTime);if(!t.collected.includes(coin.id)&&touchesCoin(this,coin)){if(this.events.coin)this.events.coin(coin);else t.collected.push(coin.id);}}
   if(section.index<=this.state.index&&q.s>section.length-1.5&&this.grounded&&!t.completed.includes(section.index)){t.completed.push(section.index);this.events.checkpoint?.('Traversal complete',section);}
  }if(this.course.some(s=>s.platforms.some(r=>r.fragile&&Math.hypot(p.x-r.x,p.z-r.z)<r.r+.1)))safe=false;const enemy=this.combat?.blocking;if(enemy&&courseCoordinates(enemy.section,p).s>2)safe=false;if(this.grounded&&this.jumpStage==='ground'&&safe&&this.support()!==null){t.safe={x:p.x,z:p.z,y:this.y,heading:this.events.heading?.()??this.heading};}
 }
 step(dt,input={x:0,z:0}){this.passiveCarry=false;this.moving=false;this.blocked=false;const count=Math.max(1,Math.ceil(Math.min(dt,1)/.016));for(let k=0;k<count;k++){const d=Math.min(dt,1)/count;const previousTime=this.courseTime;this.courseTime+=d;this.trials?.carry(previousTime,this.courseTime);this.updateCrumble(d);this.recovery=Math.max(0,this.recovery-d);this.invincible=Math.max(0,this.invincible-d);if(this.recovery>0)continue;this.cooldown=Math.max(0,this.cooldown-d);if(this.jumpBuffer>0){this.jumpBuffer=Math.max(0,this.jumpBuffer-d);if(this.grounded&&this.jumpStage==='ground'&&this.cooldown<=0)this.requestJump();}this.jumpTimer+=d;if(this.jumpStage==='anticipation'&&this.jumpTimer>=.1){this.jumpStage='air';this.grounded=false;const tuning=jumpTuning(this.jumpAssisted?0:this.level);this.vy=tuning.velocity;this.airTime=0;this.flightDuration=tuning.flight;}
   const running=this.runner?.engage(this);
   // On a run the controller places the creature (moving track); otherwise the usual walking below.
   if(running){this.stop();if(this.rushEnabled){this.rush??=new RushMotion();this.rush.update(d,{moving:true,safe:true,gateDistance:Infinity,recovery:false,blocked:false});}this.runner.advance(this,d);}
   const direct=Math.hypot(input.x,input.z)>.05;let moveSpeed=2.6;if(this.rushEnabled&&!running){this.rush??=new RushMotion();const section=this.section,node=activeNode(this.state),safe=section?.kind==='coins'&&!section.trial&&!this.combat?.blocking&&!this.trials?.blocking;moveSpeed=this.rush.update(d,{moving:direct,safe,gateDistance:node?Math.hypot(node.x-this.player.x,node.z-this.player.z):0,recovery:this.recovery>0,blocked:this.blocked});if(!direct)moveSpeed=2.6;}if(direct)this.stop();const target=running?null:direct?{x:this.player.x+input.x,z:this.player.z+input.z}:this.path[0];if(target){const dx=target.x-this.player.x,dz=target.z-this.player.z,length=Math.hypot(dx,dz),step=Math.min(length,moveSpeed*d*(direct?Math.min(1,Math.hypot(input.x,input.z)):1));if(length<.04&&!direct)this.path.shift();else{const mx=dx/(length||1)*step,mz=dz/(length||1)*step;
    if(!running&&this.course&&this.mode==='relaxed'&&this.grounded&&!this.jumping&&this.cooldown<=0&&this.support({x:this.player.x+mx*5,z:this.player.z+mz*5})===null){this.requestJump({assisted:true});this.events.assist?.();continue;}
    const move=(x,z)=>{if(!this.clear(x,z))return false;this.player={x,z};return true;},old={...this.player},oldHeading=this.heading;this.heading=Math.atan2(dx,dz);if(!move(old.x+mx,old.z+mz)&&!move(old.x+mx,old.z)&&!move(old.x,old.z+mz)){this.heading=oldHeading;this.blocked=true;this.rush?.reset();if(!direct)this.stop();}else{this.moving=true;this.heading=Math.atan2(this.player.x-old.x,this.player.z-old.z);}}
   }
   const surface=this.support(),before=this.y;if(this.grounded&&this.jumpStage!=='anticipation'&&(surface===null||surface<this.y-.26)){this.grounded=false;this.jumpStage='air';this.vy=0;this.airTime=0;this.flightDuration=.6;}if(this.grounded&&surface!==null&&(this.jumpStage!=='anticipation'||surface>=this.y))this.y=surface;
   if(!this.grounded){this.airTime+=d;this.vy-=JUMP_GRAVITY*d;this.y+=this.vy*d;if(surface!==null&&this.vy<=0&&before>=surface-.025&&this.y<=surface){this.y=surface;this.vy=0;this.grounded=true;this.jumpStage='landing';this.jumpTimer=0;this.cooldown=.16;}else if(this.y<-.85){this.retry('fall');continue;}}else if(this.jumpStage==='landing'&&this.jumpTimer>=.14)this.jumpStage='ground';
   if(running&&this.recovery<=0)this.runner.collide(this);
   this.combat?.step(d);this.trials?.step(d);if(this.recovery>0)continue;this.updateTravel();if(!this.path.length&&this.destination&&!this.jumping){const id=this.destination;this.destination=null;this.onArrive(id);}
  }
 }
}
